"""Freeze complete task book BEFORE generating any concentration or source scores."""
import csv, hashlib, json, pathlib, time
from datetime import datetime, timezone
BASE=pathlib.Path(__file__).resolve().parents[1]
OUT=BASE/'outputs/PMFS_R3_R5_CONTINUOUS_20261011'
def main():
    if (OUT/'R4_PREREGISTRATION.json').exists(): raise RuntimeError('Already frozen; do not overwrite')
    candidates=[{'id':i,'row':r,'col':c,'x_m':(c+.5)*.5,'y_m':(r+.5)*.5} for i,(r,c) in enumerate((r,c) for r in [4,8,12,16,20] for c in [4,8,12,16,20])]
    receivers=[(r,c) for r in [1,6,11,17,22] for c in ([1,6,11,17,22] if ([1,6,11,17,22].index(r)%2==0) else [22,17,11,6,1])]
    route=[{'event':i+1,'step':10*(i+1),'time_s':2*(i+1),'row':receivers[i%25][0],'col':receivers[i%25][1]} for i in range(50)]
    tasks=[]
    for split,sources,angles,phases,seedbase in [('development',[0,12,24],[0,.6,-.6],[.1,.9,1.7],401000),('heldout',[4,8,16],[.3,-.4,.8],[.4,1.2,2.1],701000)]:
        for source in sources:
            for ri,regime in enumerate(['constant','slow','fast']):
                for realization in range(2):
                    i=len(tasks); seed=seedbase+source*100+ri*10+realization
                    tasks.append({'task_id':f'T{i:02d}','split':split,'true_source_id':source,'regime':regime,'base_angle_rad':angles[ri],'phase_rad':phases[ri],'realization':realization,'release_seed':seed+1,'wind_truth_seed':seed+2,'gas_sensor_seed':seed+3,'wind_sensor_seed':seed+4,'inference_seed':seed+10000})
    d={'created_UTC':datetime.now(timezone.utc).isoformat(),'scope':'2D periodic controlled numerical transport, matched common solver; no 3D/lakeshore/real sensor claim',
       'physical':{'shape':[24,24],'dx_m':.5,'dy_m':.5,'slab_height_m':1.,'dt_s':.2,'steps':500,'duration_s':100.,'D_m2_s':.05,'rate_mg_s':1.,'boundary':'periodic; mass grows by injected mass, NO finite steady solution','concentration_unit':'mg/m3 in fixed 1m slab, not ppm','source_height':'fixed slab; no vertical model','initial_concentration':0.},
       'wind':{'spatial':'uniform by explicit assumption; local instrument informative of global wind only in this mathematical domain','speed_m_s':.6,'turn_amplitude_rad':.8,'period_s':{'constant':None,'slow':70.,'fast':14.},'T_adv_s':20.,'T_w_over_T_adv':{'constant':'infinite','slow':3.5,'fast':.7},'truth_OU_stationary_sd_m_s':.015,'truth_OU_correlation_s':3.,'component_bounds_m_s':[-1.,1.],'sensor_period_steps':5,'sensor_sd_m_s':.02,'warmup_samples':10,'filter_random_walk_sd_m_s_sqrt_s':.12},
       'release':{'OU_stationary_log_sd':.08,'OU_correlation_s':10.,'lognormal_mean_corrected':True,'independent_stream_from_sensors':True},
       'sensor':{'likelihood':'left-censored additive Gaussian: y=max(0,c+noise); y=0 uses Gaussian CDF probability','sd_mg_m3':.02,'binary_threshold_mg_m3':.05,'binary_role':'deterministic diagnostic only, not multiplied as independent likelihood','field_readout':'cell average, same declared grid for all models'},
       'inference':{'particles_per_source':24,'source_prior':'uniform 1/25','source_support':candidates,'prefixes':[20,35,50],'methods':['B0_FIXED','B1_TRANSIENT','B2_JOINT_PF','WIND_ORACLE'],'gas_particle_process':'same stationary OU release law as truth; seed distinct','resampling':'systematic when conditional ESS < K/2; no rejuvenation or fitted thresholds','B0':'initial warmup wind estimate held fixed, continuing gas state; fixed-wind approximation NOT steady solution or native PMFS','B1':'ordinary continuous FV state with causal local-wind Kalman mean and source-conditional release PF','B2':'ordinary joint wind/release/plume source-conditional PF, analytic adapted Gaussian wind observation proposal','WIND_ORACLE':'true wind at each step only for diagnostic upper bound; still release uncertainty','all_methods_continuous_sensor':True,'no_true_source_in_runner':True,'no_future_inputs':True,'end_to_end_profile_budget_s_per_task':120.},
       'decision':{'main':'feasible candidate medoid minimizing posterior expected Euclidean distance in planar world coordinates','MAP':'auxiliary 0-1 decision','mean':'auxiliary squared-distance decision','Top5':'auxiliary weighted highest ceil(25*.05)=2 candidates, NOT official PMFS metric','coverage':'90% highest posterior density set on the 25 atomic source points','CRPS':'prequential continuous predictive mixture Gaussian CRPS for latent raw signal; observed censorship noted; primary predictive proper score uses censored likelihood'},
       'gates':{'candidate_pitch_m':2.,'ordinary_mean_distance_max_m':2.,'ordinary_coverage90_min':.8,'ordinary_prequential_raw_CRPS_max_mg_m3':.05,'static_gap_mean_B0_minus_B1_min_m':.5,'static_gap_min_dynamic_source_regime_groups':2,'constant_negative_control_mean_distance_delta_max_m':.5,'minimum_effect_for_memory_m':.5,'memory_admission':'Need ordinary methods cross-group gap specifically attributable to unresolved historical state or deployed cost >120s/task, excluding finite particle/likelihood/process mismatch, support and observations. Failure of arbitrary accuracy target alone does not admit.','grouping':'whole source x concrete wind history x independently generated release/wind/sensor realization; events never independent experimental units','development_selection':'no parameter fitting, fixed implementations. Select B1 or B2 for ordinary-sufficiency declaration by development mean Euclidean endpoint; apply unchanged to heldout once. Report both.'},
       'route':route,'tasks':tasks,'limits':{'batch_wall_s':14400,'RSS_bytes':1073741824,'new_data_bytes':8589934592,'free_disk_min_bytes':4294967296,'threads':1},
       'guardrail':'No retuning after gas observations or heldout scores. No ROS/Nav2, no CFD/GADEN, no new GPU or learned model absent R5 admission.'}
    path=OUT/'R4_PREREGISTRATION.json'; path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    digest=hashlib.sha256(path.read_bytes()).hexdigest(); (OUT/'R4_PREREGISTRATION.sha256').write_text(digest+'  R4_PREREGISTRATION.json\n',encoding='ascii')
    with (OUT/'R4_FROZEN_TASK_BOOK.csv').open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(tasks[0]),lineterminator='\n');w.writeheader();w.writerows(tasks)
    (OUT/'R4_WIND_HISTORY_CONTRACT.md').write_text('''# R4 冻结风历史、信息与预算合同\n\n25个合法原子源点；开发18与未见源/具体风历史18，独立释放、风扰动及传感器随机流。所有方法同一50事件固定蛇形路线，不由真源选路线，保存20/35/50前缀。参数与种子见JSON和任务表，SHA在任何气体生成前保存。\n\n二维24×24周期域12m×12m，质量守恒显式上风扩散，dt=0.2s，D=0.05m²/s，持续1mg/s窄随机释放；100s。风恒定/慢变/快变，Tw/Tadv为∞/3.5/0.7。局部测风每1秒；真风另存评价目录，只有ORACLE可读。当前风相同但历史不同的资格测试检查气体记忆，无拼接静态羽流。\n\n周期域持续注入没有有限稳态解。B0是初始固定风下的连续瞬态近似；B1普通瞬态推进和因果风滤波；B2普通联合风/源条件粒子滤波。B0并非PMFS/ADApprox官方代码，R4也不是原生导航复现。B1/B2已有完整气体状态记忆，不因基线失败自动断言需要神经记忆。\n\n气体单位mg/m³、固定1m厚层，无ppm/PID标定。每个事件只累加一次正确左删失Gaussian似然，不重复二值事件。真实与推断共用声明的离散FV算子，属于匹配求解器机制测试，不是独立物理验证。\n\n主端点统一可行欧氏风险动作，辅报MAP/均值/Top5/NLL/Brier/能量分数及覆盖和预测成本。普通充分性是本数值任务的预注册要求，不改PMFS官方成功门。随机任务不是相邻帧重复。全部零检出和失败保留。\n\n新科学计算单批≤4小时、RSS≤1GiB、新数据≤8GiB、余盘≥4GiB。前置无标签测试和profiling后一次执行；不调源、噪声、风角、粒子数或阈值。R5仅因具体必要性入门，不强求正信号。\n''',encoding='utf-8')
    with (OUT/'EXECUTION_LEDGER.jsonl').open('a',encoding='utf-8') as f: f.write(json.dumps({'UTC':d['created_UTC'],'event':'R4_PREREGISTRATION_FROZEN_BEFORE_DATA','sha256':digest},ensure_ascii=False)+'\n')
    print(json.dumps({'frozen_sha256':digest,'tasks':len(tasks),'sources':len(candidates)}))
if __name__=='__main__':main()
